3	import (
4		"reflect"
5		"strings"
6		"testing"
7		"time"
8	)
9	
10	// TestAssignOwnerReplayRebuildsHandover pins the recovery of a legal owner
11	// handover: the saved records are the only source after a restart, so the
12	// rebuilt owner, membership, versions, history, operators, target names, and
13	// timestamps must match the successful actions one for one.
14	func TestAssignOwnerReplayRebuildsHandover(t *testing.T) {
15		times := seededTimes(4)
16		records := []Record{
17			NewCreationRecord(Creation{ID: "I1", Title: "T", Service: "gateway", Operator: "Alice"}, times[0]),
18			NewActionRecord(Request{IncidentID: "I1", ActionID: "p1", Operator: "alice",
19				ExpectedVersion: 1, Type: ActionAddParticipant, Content: "bob"}, times[1]),
20			NewActionRecord(Request{IncidentID: "I1", ActionID: "p2", Operator: "alice",
21				ExpectedVersion: 2, Type: ActionAddParticipant, Content: "Carol"}, times[2]),
22			NewActionRecord(Request{IncidentID: "I1", ActionID: "o1", Operator: "bob",
23				ExpectedVersion: 3, Type: ActionAssignOwner, Content: "Carol"}, times[3]),
24		}
25	
26		reg := NewRegistry(&fakeEvents{}, nil)
27		for _, record := range records {
28			if err := reg.Load(record); err != nil {
29				t.Fatalf("load: %v", err)
30			}
31		}
32	
33		inc, err := reg.Get("I1")
34		if err != nil {
35			t.Fatal(err)
36		}
37		if inc.Status != StatusOpen {
38			t.Fatalf("incident must stay open: %q", inc.Status)
39		}
40		// The last handover names the owner; the membership is untouched and is
41		// listed lexicographically with the original case preserved.
42		if inc.Owner != "Carol" {
43			t.Fatalf("rebuilt owner %q", inc.Owner)
44		}
45		if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Carol", "bob"}) {
46			t.Fatalf("rebuilt participants %+v", inc.Participants)
47		}
48		if inc.Version != 4 {
49			t.Fatalf("rebuilt version %d", inc.Version)
50		}
51	
52		want := []struct {
53			actionID string
54			operator string
55			action   string
56			content  string
57			version  int
58			at       time.Time
59		}{
60			{"", "Alice", ActionCreate, "T", 1, times[0]},
61			{"p1", "alice", ActionAddParticipant, "bob", 2, times[1]},
62			{"p2", "alice", ActionAddParticipant, "Carol", 3, times[2]},
63			{"o1", "bob", ActionAssignOwner, "Carol", 4, times[3]},
64		}
65		if len(inc.History) != len(want) {
66			t.Fatalf("history len %d want %d", len(inc.History), len(want))
67		}
68		for i, w := range want {
69			got := inc.History[i]
70			if got.ActionID != w.actionID || got.Operator != w.operator || got.Action != w.action ||
71				got.Content != w.content || got.Version != w.version || !got.At.Equal(w.at) {
72				t.Fatalf("history[%d] %+v want %+v", i, got, w)
73			}
74		}
75	
76		// A retry of the saved handover returns its first result (version 4) and
77		// counts as no new action: version and history stay put.
78		res, err := reg.Apply(Request{IncidentID: "I1", ActionID: "o1", Operator: "bob",
79			ExpectedVersion: 3, Type: ActionAssignOwner, Content: "Carol"})
80		if err != nil {
81			t.Fatalf("retry after replay: %v", err)
82		}
83		if res != (ActionResult{IncidentID: "I1", ActionID: "o1", Version: 4}) {
84			t.Fatalf("retry result %+v", res)
85		}
86		again, _ := reg.Get("I1")
87		if again.Version != 4 || len(again.History) != 4 || again.Owner != "Carol" {
88			t.Fatalf("retry must not count as another action: %+v", again)
89		}
90	}
91	
92	// TestAssignOwnerReplayIsCaseSensitive guards case-sensitive handover
93	// targets during recovery: with only "Bob" in the list, "bob" is a stranger;
94	// once both have joined, handing to one keeps that exact name as owner and
95	// leaves the other's participation untouched.
96	func TestAssignOwnerReplayIsCaseSensitive(t *testing.T) {
97		t0 := time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
98		at := func(sec int) time.Time { return t0.Add(time.Duration(sec) * time.Second) }
99		creation := NewCreationRecord(Creation{ID: "I1", Title: "T", Service: "gateway", Operator: "Alice"}, at(0))
100	
101		t.Run("lowercase name is not the joined participant", func(t *testing.T) {
102			addBob := NewActionRecord(Request{IncidentID: "I1", ActionID: "p1", Operator: "alice",
103				ExpectedVersion: 1, Type: ActionAddParticipant, Content: "Bob"}, at(1))
104			// Fresh action id, sequential version, every field legal: the only
105			// thing wrong is the handover target.
106			handToBob := NewActionRecord(Request{IncidentID: "I1", ActionID: "o1", Operator: "alice",
107				ExpectedVersion: 2, Type: ActionAssignOwner, Content: "bob"}, at(2))
108			if err := assertRecordWellFormed(handToBob); err != nil {
109				t.Fatal(err)
110			}
111	
112			reg := NewRegistry(&fakeEvents{}, nil)
113			if err := reg.Load(creation); err != nil {
114				t.Fatal(err)
115			}
116			if err := reg.Load(addBob); err != nil {
117				t.Fatal(err)
118			}
119			err := reg.Load(handToBob)
120			if err == nil || !strings.Contains(err.Error(), "non-participant") ||
121				!strings.Contains(err.Error(), `"bob"`) {
122				t.Fatalf("handover to a merely case-similar name must fail the membership rule, got %v", err)
123			}
124	
125			inc, _ := reg.Get("I1")
126			if inc.Owner != "Alice" {
127				t.Fatalf("owner must not move on a rejected handover: %q", inc.Owner)
128			}
129			if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Bob"}) {
130				t.Fatalf("membership must not gain the target: %+v", inc.Participants)
131			}
132			if inc.Version != 2 || len(inc.History) != 2 {
133				t.Fatalf("rejected record must not become a version/history entry: %+v", inc)
134			}
135		})
136	
137		t.Run("both names joined are distinct handover targets", func(t *testing.T) {
138			records := []Record{
139				creation,
140				NewActionRecord(Request{IncidentID: "I1", ActionID: "p1", Operator: "alice",
141					ExpectedVersion: 1, Type: ActionAddParticipant, Content: "bob"}, at(1)),
142				NewActionRecord(Request{IncidentID: "I1", ActionID: "p2", Operator: "alice",
143					ExpectedVersion: 2, Type: ActionAddParticipant, Content: "Bob"}, at(2)),
144				NewActionRecord(Request{IncidentID: "I1", ActionID: "o1", Operator: "alice",
145					ExpectedVersion: 3, Type: ActionAssignOwner, Content: "bob"}, at(3)),
146				NewActionRecord(Request{IncidentID: "I1", ActionID: "o2", Operator: "alice",
147					ExpectedVersion: 4, Type: ActionAssignOwner, Content: "Bob"}, at(4)),
148			}
149			reg := NewRegistry(&fakeEvents{}, nil)
150			for _, record := range records {
151				if err := reg.Load(record); err != nil {
152					t.Fatalf("load: %v", err)
153				}
154			}
155			inc, _ := reg.Get("I1")
156			// The last handover preserves the capitalized target verbatim.
157			if inc.Owner != "Bob" {
158				t.Fatalf("owner %q want Bob", inc.Owner)
159			}
160			if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Bob", "bob"}) {
161				t.Fatalf("both case variants remain participants: %+v", inc.Participants)
162			}
163			if inc.Version != 5 || len(inc.History) != 5 {
164				t.Fatalf("version/history %+v", inc)
165			}
166		})
167	}
168	
169	// TestReplayRejectsIllegalOwnerHandover is the core regression for
170	// "accepted at recovery but refused at the request entry". Both illegal
171	// handovers are otherwise flawless records (legal fields and timestamp,
172	// sequential expected_version, a fresh action id), so a rejection must come
173	// from the handover rule itself — whether the bad record sits at the tail or
174	// ahead of other, independently legal records. A failed Load leaves the
175	// already-saved content unchanged: no auto-join for the target, no default
176	// owner substituted, and the following records are never applied.
177	func TestReplayRejectsIllegalOwnerHandover(t *testing.T) {
178		t0 := time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
179		at := func(sec int) time.Time { return t0.Add(time.Duration(sec) * time.Second) }
180	
181		cases := []struct {
182			name         string
183			prefix       []Record
184			bad          Record
185			follow       Record
186			wantVersion  int
187			wantOwner    string
188			wantMembers  []string
189			wantErrPart  string
190			wantTarget   string
191			liveCurrentV int
192		}{
193			{
194				name: "target never joined",
195				prefix: []Record{
196					NewCreationRecord(Creation{ID: "I1", Title: "T", Service: "gateway", Operator: "Alice"}, at(0)),
197					NewActionRecord(Request{IncidentID: "I1", ActionID: "p1", Operator: "alice",
198						ExpectedVersion: 1, Type: ActionAddParticipant, Content: "bob"}, at(1)),
199				},
200				bad: NewActionRecord(Request{IncidentID: "I1", ActionID: "o1", Operator: "alice",
201					ExpectedVersion: 2, Type: ActionAssignOwner, Content: "carol"}, at(2)),
202				// The following note was (wrongly, in a consistent world) written
203				// against the version the bad handover would reach, so a recovery
204				// path that accepts the handover would accept this too and start
205				// successfully: the test then fails because startup did not abort.
206				follow: NewActionRecord(Request{IncidentID: "I1", ActionID: "n1", Operator: "alice",
207					ExpectedVersion: 3, Type: ActionNote, Content: "after the bad handover"}, at(3)),
208				wantVersion:  2,
209				wantOwner:    "Alice",
210				wantMembers:  []string{"Alice", "bob"},
211				wantErrPart:  "non-participant",
212				wantTarget:   `"carol"`,
213				liveCurrentV: 2,
214			},
215			{
216				name: "target is the current owner",
217				prefix: []Record{
218					NewCreationRecord(Creation{ID: "I1", Title: "T", Service: "gateway", Operator: "Alice"}, at(0)),
219					NewActionRecord(Request{IncidentID: "I1", ActionID: "p1", Operator: "alice",
220						ExpectedVersion: 1, Type: ActionAddParticipant, Content: "bob"}, at(1)),
221					NewActionRecord(Request{IncidentID: "I1", ActionID: "o0", Operator: "alice",
222						ExpectedVersion: 2, Type: ActionAssignOwner, Content: "bob"}, at(2)),
223				},
224				bad: NewActionRecord(Request{IncidentID: "I1", ActionID: "o1", Operator: "alice",
225					ExpectedVersion: 3, Type: ActionAssignOwner, Content: "bob"}, at(3)),
226				// Same rationale as above: sequential with the bad handover's
227				// would-be version, so accepting the no-op handover lets startup
228				// proceed past it.
229				follow: NewActionRecord(Request{IncidentID: "I1", ActionID: "n1", Operator: "alice",
230					ExpectedVersion: 4, Type: ActionNote, Content: "after the bad handover"}, at(4)),
231				wantVersion:  3,
232				wantOwner:    "bob",
233				wantMembers:  []string{"Alice", "bob"},
234				wantErrPart:  "itself",
235				wantTarget:   `"bob"`,
236				liveCurrentV: 3,
237			},
238		}
239	
240		for _, tc := range cases {
241			t.Run(tc.name, func(t *testing.T) {
242				badReq := tc.bad.Action.Request
243	
244				// The bad record and the trailing record must themselves be
245				// complete, well-formed records: failure is the handover rule, not
246				// a missing field, a timestamp problem, or JSON corruption.
247				if err := assertRecordWellFormed(tc.bad); err != nil {
248					t.Fatalf("bad record: %v", err)
249				}
250				if err := assertRecordWellFormed(tc.follow); err != nil {
251					t.Fatalf("following record: %v", err)
252				}
253				if _, err := NormalizeRequest(badReq); err != nil {
254					t.Fatalf("bad request normalizes fine on its own: %v", err)
255				}
256				if badReq.ExpectedVersion != tc.wantVersion {
257					t.Fatalf("expected_version %d must be the current version %d",
258						badReq.ExpectedVersion, tc.wantVersion)
259				}
260	
261				// Parity: the live request entry rejects the same normalized
262				// request as a 409-style conflict at the same version.
263				live, _, _ := newTestRegistry(&fakeEvents{})
264				if _, err := live.Create(
265					Creation{ID: "I1", Title: "T", Service: "gateway", Operator: "Alice"}); err != nil {
266					t.Fatal(err)
267				}
268				for _, record := range tc.prefix[1:] {
269					if _, err := live.Apply(record.Action.Request); err != nil {
270						t.Fatalf("live prefix: %v", err)
271					}
272				}
273				_, liveErr := live.Apply(badReq)
274				if !IsConflictError(liveErr) || CurrentVersionOf(liveErr) != tc.liveCurrentV {
275					t.Fatalf("live request path must reject the handover: %v", liveErr)
276				}
277				liveInc, _ := live.Get("I1")
278				if liveInc.Version != tc.wantVersion || liveInc.Owner != tc.wantOwner {
279					t.Fatalf("rejected live request must leave state put: %+v", liveInc)
280				}
281	
282				for _, withFollow := range []bool{false, true} {
283					placement := "at the tail"
284					if withFollow {
285						placement = "ahead of other records"
286					}
287					t.Run(placement, func(t *testing.T) {
288						// Recovery walks the log in order and stops at the first
289						// contradiction, exactly like runServe's replay loop.
290						sequence := append(append([]Record{}, tc.prefix...), tc.bad)
291						if withFollow {
292							sequence = append(sequence, tc.follow)
293						}
294						reg := NewRegistry(&fakeEvents{}, nil)
295						var err error
296						failedAt := -1
297						for i, record := range sequence {
298							if err = reg.Load(record); err != nil {
299								failedAt = i
300								break
301							}
302						}
303						if failedAt != len(tc.prefix) {
304							t.Fatalf("recovery must fail on the bad record (index %d), failed at %d: %v",
305								len(tc.prefix), failedAt, err)
306						}
307						if !strings.Contains(err.Error(), tc.wantErrPart) ||
308							!strings.Contains(err.Error(), tc.wantTarget) {
309							t.Fatalf("error must explain why the target %s is illegal: %v",
310								tc.wantTarget, err)
311						}
312						if strings.Contains(err.Error(), "expected version") {
313							t.Fatalf("failure must not be a version jump: %v", err)
314						}
315						if strings.Contains(err.Error(), "duplicate") {
316							t.Fatalf("failure must not be a reused action id: %v", err)
317						}
318	
319						inc, _ := reg.Get("I1")
320						if inc.Owner != tc.wantOwner {
321							t.Fatalf("owner %q want %q (no default substitution)", inc.Owner, tc.wantOwner)
322						}
323						if !reflect.DeepEqual(inc.Participants, tc.wantMembers) {
324							t.Fatalf("membership changed around a failed handover: %+v", inc.Participants)
325						}
326						if inc.Version != tc.wantVersion || len(inc.History) != tc.wantVersion {
327							t.Fatalf("state must stay at the prefix: %+v", inc)
328						}
329						for _, entry := range inc.History {
330							if entry.Action == ActionNote && entry.Content == "after the bad handover" {
331								t.Fatal("records following the bad handover must not be applied")
332							}
333							if entry.ActionID == "o1" && entry.Action == ActionAssignOwner {
334								t.Fatal("the rejected handover must not appear in history")
335							}
336						}
337					})
338				}
339			})
340		}
341	}
342	
343	// assertRecordWellFormed verifies that a record survives the durable
344	// round-trip: strict JSON decode, re-validation, and an equal round-trip. A
345	// record used in a rule-failure test must pass all of these so the rejection
346	// under test is attributable to the handover rules alone.
347	func assertRecordWellFormed(record Record) error {
348		data, err := MarshalRecord(record)
349		if err != nil {
350			return err
351		}
352		back, err := DecodeRecord(data)
353		if err != nil {
354			return err
355		}
356		if back.Kind != RecordAction || back.Action.Request != record.Action.Request || !back.At.Equal(record.At) {
357			return &ValidationError{Reason: "record round-trip mismatch"}
