1	package httpapi
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"net/http"
9		"net/http/httptest"
10		"strings"
11		"sync"
12		"testing"
13		"time"
14	
15		"github.com/cocosolocoder/signalroom/internal/events"
16		"github.com/cocosolocoder/signalroom/internal/incidents"
17	)
18	
19	type fakeIncidentStorage struct {
20		mu       sync.Mutex
21		failNext bool
22		poisoned bool
23		records  []incidents.Record
24	}
25	
26	func (f *fakeIncidentStorage) AppendRecord(record incidents.Record) error {
27		f.mu.Lock()
28		defer f.mu.Unlock()
29		if f.failNext {
30			f.poisoned = true
31			f.failNext = false
32			return errBoom
33		}
34		f.records = append(f.records, record)
35		return nil
36	}
37	
38	func (f *fakeIncidentStorage) Poisoned() bool {
39		f.mu.Lock()
40		defer f.mu.Unlock()
41		return f.poisoned
42	}
43	
44	var errBoom = errors.New("simulated incident write failure")
45	
46	func newIncidentServer(t *testing.T) (*httptest.Server, *fakeIncidentStorage, *events.Timeline, *incidents.Registry) {
47		t.Helper()
48		tl := events.NewTimeline()
49		eventStore := &fakeStorage{cursorKey: []byte("test-cursor-key-0123456789ab")}
50		incStore := &fakeIncidentStorage{}
51		reg := incidents.NewRegistry(tl, incStore.AppendRecord)
52		server := httptest.NewServer(NewHandler(tl, eventStore, eventStore, WithIncidents(reg, incStore)))
53		t.Cleanup(server.Close)
54		return server, incStore, tl, reg
55	}
56	
57	func parseEventTime(s string) time.Time {
58		t, err := time.Parse(time.RFC3339Nano, s)
59		if err != nil {
60			panic(err)
61		}
62		return t
63	}
64	
65	// number reads a JSON number that decoded into float64.
66	func number(v any) int {
67		f, _ := v.(float64)
68		return int(f)
69	}
70	
71	func ingestEvent(t *testing.T, tl *events.Timeline, id, service string) {
72		t.Helper()
73		err := tl.Load(events.Event{ID: id, Service: service, Severity: "critical", Message: "m", At: parseEventTime("2026-10-01T10:00:00Z")})
74		if err != nil {
75			t.Fatal(err)
76		}
77	}
78	
79	func doJSON(t *testing.T, server *httptest.Server, method, path, body string) (int, map[string]any) {
80		t.Helper()
81		var reader io.Reader
82		if body != "" {
83			reader = strings.NewReader(body)
84		}
85		req, err := http.NewRequest(method, server.URL+path, reader)
86		if err != nil {
87			t.Fatal(err)
88		}
89		if body != "" {
90			req.Header.Set("Content-Type", "application/json")
91		}
92		resp, err := http.DefaultClient.Do(req)
93		if err != nil {
94			t.Fatal(err)
95		}
96		defer resp.Body.Close()
97		raw, err := io.ReadAll(resp.Body)
98		if err != nil {
99			t.Fatal(err)
100		}
101		var out map[string]any
102		if len(bytes.TrimSpace(raw)) > 0 {
103			if err := json.Unmarshal(raw, &out); err != nil {
104				t.Fatalf("decode %q: %v", raw, err)
105			}
106		}
107		return resp.StatusCode, out
108	}
109	
110	func createIncident(t *testing.T, server *httptest.Server) {
111		t.Helper()
