456		var wg sync.WaitGroup
457		start := make(chan struct{})
458		statuses := make([]int, n)
459		for i := 0; i < n; i++ {
460			wg.Add(1)
461			go func(i int) {
462				defer wg.Done()
463				<-start
464				req, _ := http.NewRequest(http.MethodPost, server.URL+"/incidents/INC-1/actions",
465					strings.NewReader(`{"action_id":"dup","operator":"bob","expected_version":1,"action":"add_note","content":"same"}`))
466				req.Header.Set("Content-Type", "application/json")
467				resp, err := http.DefaultClient.Do(req)
468				if err != nil {
469					statuses[i] = -1
470					return
471				}
472				resp.Body.Close()
473				statuses[i] = resp.StatusCode
474			}(i)
475		}
476		close(start)
477		wg.Wait()
478		for i, code := range statuses {
479			if code != http.StatusOK {
480				t.Fatalf("duplicate request %d: want 200 replay, got %d", i, code)
481			}
